import numpy as np

def f(u):
    return np.sin(u)

def f_prime(u):
    return np.cos(u)

def g(x):
    return x**2 + 1

def g_prime(x):
    return 2 * x

def h(x):
    return f(g(x))

def h_prime(x):
    return f_prime(g(x)) * g_prime(x)

x0 = 1.5
u_val = g(x0)
f_of_u = f(u_val)
g_val = g(x0)
h_val = h(x0)
h_prime_val = h_prime(x0)

h_prime_numerical = (h(x0 + 1e-7) - h(x0 - 1e-7)) / (2e-7)

print(f"g({x0}) = {g_val}")
print(f"f(g({x0})) = {h_val}")
print(f"h'({x0}) = {h_prime_val}")
print(f"h'({x0}) numerical = {h_prime_numerical}")
print(f"Error: {abs(h_prime_val - h_prime_numerical):.2e}")
